    function escapeHtml(str) {
        return String(str ?? '').replace(/[&<>"']/g, (c) => {
            switch (c) {
                case '&':
                    return '&amp;';
                case '<':
                    return '&lt;';
                case '>':
                    return '&gt;';
                case '"':
                    return '&quot;';
                default:
                    return '&#39;';
            }
        });
    }
